/*!
 * QR Code generator — self-contained, no dependencies
 * Compatible with qrcodejs API: new QRCode(el, {text, width, height, colorDark, colorLight, correctLevel})
 * Supports byte mode, versions 1-10, all error correction levels
 */
(function(w){
'use strict';

// ── GF(256) arithmetic ────────────────────────────────────────────────────────
var EXP=new Array(512),LOG=new Array(256);
(function(){
  var x=1;
  for(var i=0;i<255;i++){EXP[i]=x;LOG[x]=i;x<<=1;if(x>=256)x^=285;}
  for(var i=255;i<512;i++)EXP[i]=EXP[i-255];
  LOG[0]=0;
})();
function gfMul(a,b){return a===0||b===0?0:EXP[LOG[a]+LOG[b]];}
function gfPow(x,p){return EXP[(LOG[x]*p)%255];}

// ── Reed-Solomon ECC ──────────────────────────────────────────────────────────
function rsGeneratorPoly(n){
  var g=[1];
  for(var i=0;i<n;i++){
    var t=[1,gfPow(2,i)];
    var r=new Array(g.length+1).fill(0);
    for(var j=0;j<g.length;j++)for(var k=0;k<t.length;k++)r[j+k]^=gfMul(g[j],t[k]);
    g=r;
  }
  return g;
}
function rsEncode(data,n){
  var gen=rsGeneratorPoly(n);
  var out=data.slice().concat(new Array(n).fill(0));
  for(var i=0;i<data.length;i++){
    var c=out[i];
    if(c!==0)for(var j=0;j<gen.length;j++)out[i+j]^=gfMul(gen[j],c);
  }
  return out.slice(data.length);
}

// ── QR version / capacity tables ─────────────────────────────────────────────
// [version][eclevel] = total data codewords available for byte mode
var CAP=[[],
  [{L:19},{M:16},{Q:13},{H: 9}],
  [{L:34},{M:28},{Q:22},{H:16}],
  [{L:55},{M:44},{Q:34},{H:26}],
  [{L:80},{M:64},{Q:48},{H:36}],
  [{L:108},{M:86},{Q:62},{H:46}],
  [{L:136},{M:108},{Q:76},{H:60}],
  [{L:156},{M:124},{Q:88},{H:66}],
  [{L:194},{M:154},{Q:110},{H:86}],
  [{L:232},{M:182},{Q:132},{H:100}],
  [{L:274},{M:216},{Q:154},{H:122}]
];
var ECKEY=['L','M','Q','H'];
function getCap(v,ecIdx){return CAP[v][ecIdx][ECKEY[ecIdx]];}

// EC block structure [version][ecIdx] = {n, b1, d1, b2, d2}
// n=ec codewords per block, b1=group1 blocks, d1=group1 data cw, b2,d2=group2
var ECB=[[],
  [{n:7,b1:1,d1:19,b2:0,d2:0},{n:10,b1:1,d1:16,b2:0,d2:0},{n:13,b1:1,d1:13,b2:0,d2:0},{n:17,b1:1,d1:9,b2:0,d2:0}],
  [{n:10,b1:1,d1:34,b2:0,d2:0},{n:16,b1:1,d1:28,b2:0,d2:0},{n:22,b1:1,d1:22,b2:0,d2:0},{n:28,b1:1,d1:16,b2:0,d2:0}],
  [{n:15,b1:1,d1:55,b2:0,d2:0},{n:26,b1:1,d1:44,b2:0,d2:0},{n:18,b1:2,d1:17,b2:0,d2:0},{n:22,b1:2,d1:13,b2:0,d2:0}],
  [{n:20,b1:2,d1:40,b2:0,d2:0},{n:18,b1:2,d1:32,b2:0,d2:0},{n:26,b1:2,d1:24,b2:0,d2:0},{n:16,b1:4,d1:9,b2:0,d2:0}],
  [{n:26,b1:2,d1:54,b2:0,d2:0},{n:24,b1:2,d1:43,b2:0,d2:0},{n:18,b1:2,d1:15,b2:2,d2:16},{n:22,b1:2,d1:11,b2:2,d2:12}],
  [{n:18,b1:2,d1:60,b2:0,d2:0},{n:16,b1:4,d1:27,b2:0,d2:0},{n:24,b1:4,d1:19,b2:0,d2:0},{n:28,b1:4,d1:15,b2:0,d2:0}],
  [{n:20,b1:4,d1:45,b2:0,d2:0},{n:18,b1:4,d1:31,b2:0,d2:0},{n:18,b1:2,d1:14,b2:4,d2:15},{n:26,b1:4,d1:13,b2:1,d2:14}],
  [{n:24,b1:2,d1:60,b2:2,d2:61},{n:22,b1:2,d1:38,b2:2,d2:39},{n:22,b1:4,d1:18,b2:2,d2:19},{n:26,b1:4,d1:14,b2:2,d2:15}],
  [{n:30,b1:3,d1:58,b2:2,d2:59},{n:22,b1:3,d1:36,b2:2,d2:37},{n:20,b1:4,d1:16,b2:4,d2:17},{n:24,b1:4,d1:12,b2:4,d2:13}],
  [{n:18,b1:4,d1:69,b2:0,d2:0},{n:26,b1:4,d1:43,b2:1,d2:44},{n:24,b1:6,d1:19,b2:2,d2:20},{n:28,b1:6,d1:15,b2:2,d2:16}]
];

// Alignment pattern centres for versions 2-10
var ALIGN=[[],[],[6,18],[6,22],[6,26],[6,30],[6,34],[6,22,38],[6,24,42],[6,26,46],[6,28,50]];

// Remainder bits per version
var REM=[0,0,7,0,0,0,0,0,0,0,0];

// ── Bit stream builder ────────────────────────────────────────────────────────
function BitStream(){this.bits=[];}
BitStream.prototype.push=function(val,len){
  for(var i=len-1;i>=0;i--)this.bits.push((val>>i)&1);
};
BitStream.prototype.length=function(){return this.bits.length;};
BitStream.prototype.toCW=function(){
  var out=[],b=this.bits;
  for(var i=0;i<b.length;i+=8){
    var byte=0;for(var j=0;j<8;j++)byte=(byte<<1)|(b[i+j]||0);
    out.push(byte);
  }
  return out;
};

// ── Encode byte-mode data to codewords with EC ───────────────────────────────
function encodeData(text,v,ecIdx){
  var bs=new BitStream();
  bs.push(4,4); // byte mode indicator
  bs.push(text.length,8); // char count (8 bits for v<=9)
  for(var i=0;i<text.length;i++)bs.push(text.charCodeAt(i)&0xFF,8);
  // terminator + padding
  var total=getCap(v,ecIdx)*8;
  for(var i=0;i<4&&bs.length()<total;i++)bs.push(0,1);
  while(bs.length()%8!==0)bs.push(0,1);
  var pads=[0xEC,0x11],pi=0;
  while(bs.length()<total)bs.push(pads[pi++%2],8);

  var cw=bs.toCW();
  var info=ECB[v][ecIdx];
  var blocks=[],ecBlocks=[],idx=0;
  for(var i=0;i<info.b1;i++){blocks.push(cw.slice(idx,idx+info.d1));idx+=info.d1;}
  for(var i=0;i<info.b2;i++){blocks.push(cw.slice(idx,idx+info.d2));idx+=info.d2;}
  for(var i=0;i<blocks.length;i++)ecBlocks.push(rsEncode(blocks[i],info.n));

  // interleave data
  var res=[];
  var maxD=Math.max.apply(null,blocks.map(function(b){return b.length;}));
  for(var i=0;i<maxD;i++)for(var b=0;b<blocks.length;b++)if(i<blocks[b].length)res.push(blocks[b][i]);
  for(var i=0;i<ecBlocks[0].length;i++)for(var b=0;b<ecBlocks.length;b++)res.push(ecBlocks[b][i]);

  // to bits
  var out=[];
  for(var i=0;i<res.length;i++)for(var j=7;j>=0;j--)out.push((res[i]>>j)&1);
  for(var i=0;i<REM[v];i++)out.push(0);
  return out;
}

// ── Matrix helpers ────────────────────────────────────────────────────────────
function makeMatrix(n){
  var m=[];for(var i=0;i<n;i++){m.push([]);for(var j=0;j<n;j++)m[i].push(-1);}
  return m;
}

function setModule(m,r,c,val){
  if(r>=0&&r<m.length&&c>=0&&c<m.length)m[r][c]=val;
}

function putFinder(m,r,c){
  for(var i=-1;i<=7;i++)for(var j=-1;j<=7;j++){
    if(r+i<0||r+i>=m.length||c+j<0||c+j>=m.length)continue;
    var v=(i>=0&&i<=6&&(j===0||j===6))||(j>=0&&j<=6&&(i===0||i===6))||(i>=2&&i<=4&&j>=2&&j<=4)?1:0;
    m[r+i][c+j]=v;
  }
}

function putAlignment(m,r,c){
  for(var i=-2;i<=2;i++)for(var j=-2;j<=2;j++){
    m[r+i][c+j]=(Math.abs(i)===2||Math.abs(j)===2||i===0&&j===0)?1:0;
  }
}

function setupFunctionModules(m,v){
  var n=m.length;
  putFinder(m,0,0);putFinder(m,n-7,0);putFinder(m,0,n-7);
  // timing
  for(var i=8;i<n-8;i++){
    if(m[6][i]===-1)m[6][i]=m[i][6]=i%2===0?1:0;
  }
  // dark module
  m[n-8][8]=1;
  // alignment patterns
  var pos=ALIGN[v]||[];
  for(var i=0;i<pos.length;i++)for(var j=0;j<pos.length;j++){
    if(m[pos[i]][pos[j]]===-1)putAlignment(m,pos[i],pos[j]);
  }
}

function isFunctionModule(m,v,r,c){
  var n=m.length;
  if((r<9&&c<9)||(r<9&&c>=n-8)||(r>=n-8&&c<9))return true;
  if(r===6||c===6)return true;
  if(r===n-8&&c===8)return true;
  var pos=ALIGN[v]||[];
  for(var i=0;i<pos.length;i++)for(var j=0;j<pos.length;j++){
    if(Math.abs(r-pos[i])<=2&&Math.abs(c-pos[j])<=2)return true;
  }
  return false;
}

// ── Format information ────────────────────────────────────────────────────────
function formatBits(ecIdx,mask){
  // EC level bits: L=01,M=00,Q=11,H=10 (in QR format field)
  var ecBits=[1,0,3,2];
  var data=(ecBits[ecIdx]<<3)|mask;
  var g=0x537,rem=data<<10;
  for(var i=14;i>=10;i--)if(rem&(1<<i))rem^=g<<(i-10);
  return ((data<<10)|rem)^0x5412;
}

function placeFormat(m,ecIdx,mask){
  var n=m.length;
  var fmt=formatBits(ecIdx,mask);
  var seq=[0,1,2,3,4,5,7,8];
  for(var i=0;i<8;i++){
    var b=(fmt>>(14-i))&1;
    m[8][seq[i]]=b;m[seq[i]][8]=b;
  }
  for(var i=0;i<7;i++){
    var b=(fmt>>(6-i))&1;
    m[8][n-1-i]=b;m[n-8+i][8]=b;
  }
}

// ── Data placement ────────────────────────────────────────────────────────────
function placeData(m,v,bits){
  var n=m.length,idx=0,up=true;
  for(var col=n-1;col>0;col-=2){
    if(col===6)col--;
    for(var row=0;row<n;row++){
      var r=up?n-1-row:row;
      for(var k=0;k<2;k++){
        var c=col-k;
        if(!isFunctionModule(m,v,r,c)&&m[r][c]===-1){
          m[r][c]=idx<bits.length?bits[idx++]:0;
        }
      }
    }
    up=!up;
  }
}

// ── Masking ───────────────────────────────────────────────────────────────────
var MASK_FNS=[
  function(r,c){return(r+c)%2===0;},
  function(r,c){return r%2===0;},
  function(r,c){return c%3===0;},
  function(r,c){return(r+c)%3===0;},
  function(r,c){return(Math.floor(r/2)+Math.floor(c/3))%2===0;},
  function(r,c){return r*c%2+r*c%3===0;},
  function(r,c){return(r*c%2+r*c%3)%2===0;},
  function(r,c){return(r+c+r*c%3)%2===0;}
];

function applyMask(m,v,mask){
  var n=m.length,fn=MASK_FNS[mask];
  for(var r=0;r<n;r++)for(var c=0;c<n;c++){
    if(!isFunctionModule(m,v,r,c)&&fn(r,c))m[r][c]^=1;
  }
}

function penaltyScore(m){
  var n=m.length,p=0;
  for(var r=0;r<n;r++){
    var run=0,last=-1;
    for(var c=0;c<n;c++){
      if(m[r][c]===last){run++;if(run===5)p+=3;else if(run>5)p++;}
      else{last=m[r][c];run=1;}
    }
  }
  for(var c=0;c<n;c++){
    var run=0,last=-1;
    for(var r=0;r<n;r++){
      if(m[r][c]===last){run++;if(run===5)p+=3;else if(run>5)p++;}
      else{last=m[r][c];run=1;}
    }
  }
  for(var r=0;r<n-1;r++)for(var c=0;c<n-1;c++){
    var v=m[r][c];
    if(v===m[r][c+1]&&v===m[r+1][c]&&v===m[r+1][c+1])p+=3;
  }
  var dark=0;
  for(var r=0;r<n;r++)for(var c=0;c<n;c++)if(m[r][c]===1)dark++;
  p+=Math.floor(Math.abs(dark*100/(n*n)-50)/5)*10;
  return p;
}

// ── Build final QR matrix ─────────────────────────────────────────────────────
function buildQR(text,ecIdx){
  // find smallest version
  var v=-1;
  for(var i=1;i<=10;i++){
    // byte mode overhead: 4 (mode) + 8 (count) + 8*len bits, pad to codewords
    var cw=Math.ceil((4+8+8*text.length)/8);
    if(getCap(i,ecIdx)>=cw){v=i;break;}
  }
  if(v<0){console.warn('QRCode: text too long for version 1-10');return null;}

  var bits=encodeData(text,v,ecIdx);
  var n=v*4+17;
  var bestM=null,bestP=Infinity;

  for(var mask=0;mask<8;mask++){
    var m=makeMatrix(n);
    setupFunctionModules(m,v);
    placeFormat(m,ecIdx,mask);
    placeData(m,v,bits.slice());
    applyMask(m,v,mask);
    placeFormat(m,ecIdx,mask); // re-place after mask
    var p=penaltyScore(m);
    if(p<bestP){bestP=p;bestM=m;}
  }
  return bestM;
}

// ── Public QRCode class ───────────────────────────────────────────────────────
var EC={L:0,M:1,Q:2,H:3};

function QRCode(el,opts){
  if(typeof opts==='string')opts={text:opts};
  var o=opts||{};
  var text=o.text||'';
  var width=o.width||256;
  var height=o.height||256;
  var dark=o.colorDark||'#000000';
  var light=o.colorLight||'#ffffff';
  // map from qrcodejs CorrectLevel values (L=1,M=0,Q=3,H=2) to our index (L=0,M=1,Q=2,H=3)
  var clMap={0:1,1:0,2:3,3:2};
  var cl=o.correctLevel;
  var ecIdx=(cl===undefined)?1:(clMap[cl]!==undefined?clMap[cl]:1);

  this._el=el;this._opts=o;
  this._draw(text,ecIdx,width,height,dark,light);
}

QRCode.prototype._draw=function(text,ecIdx,w,h,dark,light){
  var m=buildQR(text,ecIdx);
  if(!m)return;
  var n=m.length;
  var canvas=document.createElement('canvas');
  canvas.width=w;canvas.height=h;
  var ctx=canvas.getContext('2d');
  var sz=w/n;
  ctx.fillStyle=light;ctx.fillRect(0,0,w,h);
  ctx.fillStyle=dark;
  for(var r=0;r<n;r++)for(var c=0;c<n;c++){
    if(m[r][c]===1)ctx.fillRect(Math.round(c*sz),Math.round(r*sz),Math.ceil(sz),Math.ceil(sz));
  }
  this._canvas=canvas;
  if(this._el instanceof HTMLElement){
    this._el.innerHTML='';
    this._el.appendChild(canvas);
  }
};

QRCode.prototype.makeCode=function(text){
  var o=this._opts||{};
  var cl=o.correctLevel;
  var clMap={0:1,1:0,2:3,3:2};
  var ecIdx=(cl===undefined)?1:(clMap[cl]!==undefined?clMap[cl]:1);
  this._draw(text,ecIdx,o.width||256,o.height||256,o.colorDark||'#000000',o.colorLight||'#ffffff');
};

QRCode.prototype.clear=function(){if(this._el)this._el.innerHTML='';};

QRCode.CorrectLevel={L:1,M:0,Q:3,H:2};

w.QRCode=QRCode;
})(window);
